1834	fn clause<'a>(clause: &'a TypedClause, environment: &mut Env<'a>) -> Document<'a> {
1835	    let Clause {
1836	        guard,
1837	        pattern,
1838	        alternative_patterns,
1839	        then,
1840	        ..
1841	    } = clause;
1842	
1843	    // These are required to get the alternative patterns working properly.
1844	    // Simply rendering the duplicate erlang clauses breaks the variable
1845	    // rewriting because each pattern would define different (rewritten)
1846	    // variables names.
1847	    let initial_erlang_vars = environment.erl_function_scope_vars.clone();
1848	    let initial_scope_vars = environment.current_scope_vars.clone();
1849	
1850	    let mut branches_docs = Vec::with_capacity(alternative_patterns.len() + 1);
1851	    for patterns in std::iter::once(pattern).chain(alternative_patterns) {
1852	        // Erlang doesn't support alternative patterns, so we turn each
1853	        // alternative into a branch of its own.
1854	        // For each alternative, before generating the body, we need to reset
1855	        // the variables in scope to what they are before the case expression,
1856	        // so that a branch will not interfere with the other ones!
1857	        environment.erl_function_scope_vars = initial_erlang_vars.clone();
1858	        environment.current_scope_vars = initial_scope_vars.clone();
1859	        let mut pattern_printer = PatternPrinter::new(environment);
1860	
1861	        let pattern = match patterns.as_slice() {
1862	            [pattern] => pattern_printer.print(pattern),
1863	            _ => tuple(patterns.iter().map(|pattern| {
1864	                pattern_printer.reset_variables();
1865	                pattern_printer.print(pattern)
1866	            })),
1867	        };

